PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS pay_mobile_payment_intents(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,device_id TEXT REFERENCES mobile_sync_devices(id) ON DELETE SET NULL,payload_json TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,client_created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','applied','rejected')),server_payment_id TEXT,error_message TEXT,attempts INTEGER NOT NULL DEFAULT 0,applied_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pay_mobile_payment_pending_idx ON pay_mobile_payment_intents(status,created_at);
CREATE TABLE IF NOT EXISTS pay_mobile_change_events(id INTEGER PRIMARY KEY AUTOINCREMENT,organization_id TEXT NOT NULL,collection_key TEXT NOT NULL,record_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('upsert','delete')),payload_json TEXT);
CREATE TRIGGER IF NOT EXISTS pay_mobile_change_apply AFTER INSERT ON pay_mobile_change_events BEGIN
 INSERT INTO mobile_sync_record_versions(organization_id,module_key,collection_key,record_id,version,deleted,server_updated_at,last_device_id) VALUES(NEW.organization_id,'payroll-payments',NEW.collection_key,NEW.record_id,1,CASE WHEN NEW.operation='delete' THEN 1 ELSE 0 END,CURRENT_TIMESTAMP,NULL) ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=mobile_sync_record_versions.version+1,deleted=excluded.deleted,server_updated_at=CURRENT_TIMESTAMP,last_device_id=NULL;
 DELETE FROM mobile_sync_tombstones WHERE NEW.operation='upsert' AND organization_id=NEW.organization_id AND module_key='payroll-payments' AND collection_key=NEW.collection_key AND record_id=NEW.record_id;
 INSERT INTO mobile_sync_tombstones(organization_id,module_key,collection_key,record_id,version,deleted_at,device_id) SELECT NEW.organization_id,'payroll-payments',NEW.collection_key,NEW.record_id,v.version,CURRENT_TIMESTAMP,NULL FROM mobile_sync_record_versions v WHERE NEW.operation='delete' AND v.organization_id=NEW.organization_id AND v.module_key='payroll-payments' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=excluded.version,deleted_at=CURRENT_TIMESTAMP,device_id=NULL;
 INSERT INTO mobile_sync_changes(organization_id,module_key,collection_key,record_id,version,operation,payload_json,changed_by,device_id,changed_at) SELECT NEW.organization_id,'payroll-payments',NEW.collection_key,NEW.record_id,v.version,NEW.operation,NEW.payload_json,NULL,NULL,CURRENT_TIMESTAMP FROM mobile_sync_record_versions v WHERE v.organization_id=NEW.organization_id AND v.module_key='payroll-payments' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id;
 DELETE FROM pay_mobile_change_events WHERE id=NEW.id;
END;
CREATE TRIGGER IF NOT EXISTS pay_sync_payment_insert AFTER INSERT ON payments BEGIN INSERT INTO pay_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'payments',NEW.id,'upsert',json_object('id',NEW.id,'type',NEW.type,'number',NEW.number,'contactId',NEW.contact_id,'bankAccountId',NEW.bank_account_id,'controlAccountId',NEW.control_account_id,'paymentDate',NEW.payment_date,'currency',NEW.currency,'amountMinor',NEW.amount_minor,'reference',NEW.reference,'status',NEW.status,'journalEntryId',NEW.journal_entry_id,'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)); END;
CREATE TRIGGER IF NOT EXISTS pay_sync_payment_update AFTER UPDATE ON payments BEGIN INSERT INTO pay_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'payments',NEW.id,'upsert',json_object('id',NEW.id,'type',NEW.type,'number',NEW.number,'contactId',NEW.contact_id,'bankAccountId',NEW.bank_account_id,'controlAccountId',NEW.control_account_id,'paymentDate',NEW.payment_date,'currency',NEW.currency,'amountMinor',NEW.amount_minor,'reference',NEW.reference,'status',NEW.status,'journalEntryId',NEW.journal_entry_id,'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)); END;
CREATE TRIGGER IF NOT EXISTS pay_sync_payment_delete AFTER DELETE ON payments BEGIN INSERT INTO pay_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(OLD.organization_id,'payments',OLD.id,'delete',NULL); END;
