CREATE TRIGGER IF NOT EXISTS pay_sync_run_update AFTER UPDATE ON payroll_runs BEGIN INSERT INTO pay_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'payroll-runs',NEW.id,'upsert',json_object('id',NEW.id,'number',NEW.number,'periodStart',NEW.period_start,'periodEnd',NEW.period_end,'payDate',NEW.pay_date,'status',NEW.status,'currency',NEW.currency,'grossMinor',NEW.gross_minor,'deductionsMinor',NEW.deductions_minor,'employerCostsMinor',NEW.employer_costs_minor,'netMinor',NEW.net_minor,'journalEntryId',NEW.journal_entry_id,'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)); END;
CREATE TRIGGER IF NOT EXISTS pay_sync_run_delete AFTER DELETE ON payroll_runs BEGIN INSERT INTO pay_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(OLD.organization_id,'payroll-runs',OLD.id,'delete',NULL); END;
