CREATE TRIGGER IF NOT EXISTS pay_sync_line_update AFTER UPDATE ON payroll_lines BEGIN INSERT INTO pay_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'payroll-lines',NEW.id,'upsert',json_object('id',NEW.id,'payrollRunId',NEW.payroll_run_id,'employeeId',NEW.employee_id,'grossMinor',NEW.gross_minor,'deductionsMinor',NEW.deductions_minor,'employerCostsMinor',NEW.employer_costs_minor,'netMinor',NEW.net_minor,'components',json(NEW.components),'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)); END;
