CREATE TRIGGER IF NOT EXISTS pay_sync_batch_update AFTER UPDATE ON payroll_payment_batches BEGIN INSERT INTO pay_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'payroll-payment-batches',NEW.id,'upsert',json_object('id',NEW.id,'payrollRunId',NEW.payroll_run_id,'number',NEW.number,'status',NEW.status,'bankAccountId',NEW.bank_account_id,'paymentDate',NEW.payment_date,'totalMinor',NEW.total_minor,'items',json(NEW.items),'approvedBy',NEW.approved_by,'processedAt',NEW.processed_at,'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)); END;
